<?php require_once __DIR__ . '/../app/bootstrap.php'; use App\Middleware\AuthMiddleware; use App\Services\Database; AuthMiddleware::requireRole('admin'); $q=Database::connection()->query('SELECT p.*,u.name,c.title FROM payments p JOIN users u ON u.id=p.user_id JOIN classes c ON c.id=p.class_id ORDER BY p.created_at DESC'); $rows=$q->fetchAll(); ?>
<!doctype html><html><head><script src="https://cdn.tailwindcss.com"></script></head><body class="bg-[#F5E9DA] p-6"><div class="bg-white rounded shadow p-4"><h1 class="text-2xl mb-3">Payments</h1><?php foreach($rows as $r):?><div class="border-b py-2"><?=htmlspecialchars($r['name'])?> paid $<?=htmlspecialchars((string)$r['amount'])?> for <?=htmlspecialchars($r['title'])?></div><?php endforeach;?></div></body></html>
